create extension if not exists pgcrypto;create table if not exists public.podcasts(id uuid primary key default gen_random_uuid(),creator_id uuid references auth.users(id) on delete set null,title text not null,slug text unique not null,description text,cover_url text,category text,language text default 'en',explicit boolean default false,published boolean default false,created_at timestamptz default now());create table if not exists public.episodes(id uuid primary key default gen_random_uuid(),podcast_id uuid not null references public.podcasts(id) on delete cascade,title text not null,slug text not null,description text,audio_url text not null,duration_seconds integer default 0,episode_number integer,season_number integer,published boolean default false,published_at timestamptz,created_at timestamptz default now(),unique(podcast_id,slug));create table if not exists public.podcast_subscriptions(id uuid primary key default gen_random_uuid(),podcast_id uuid not null references public.podcasts(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz default now(),unique(podcast_id,user_id));create table if not exists public.episode_progress(id uuid primary key default gen_random_uuid(),episode_id uuid not null references public.episodes(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,seconds integer default 0,completed boolean default false,updated_at timestamptz default now(),unique(episode_id,user_id));create table if not exists public.membership_plans(id uuid primary key default gen_random_uuid(),name text not null,description text,price_cents integer not null default 0,currency text default 'usd',stripe_price_id text,active boolean default true,created_at timestamptz default now());create table if not exists public.memberships(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,plan_id uuid references public.membership_plans(id),stripe_customer_id text,stripe_subscription_id text,status text,created_at timestamptz default now(),updated_at timestamptz default now(),unique(user_id));alter table public.podcasts enable row level security;alter table public.episodes enable row level security;alter table public.podcast_subscriptions enable row level security;alter table public.episode_progress enable row level security;alter table public.membership_plans enable row level security;alter table public.memberships enable row level security;create policy "published podcasts readable" on public.podcasts for select to anon,authenticated using(published=true or creator_id=(select auth.uid()));create policy "published episodes readable" on public.episodes for select to anon,authenticated using(published=true or exists(select 1 from public.podcasts p where p.id=podcast_id and p.creator_id=(select auth.uid())));create policy "own subscriptions" on public.podcast_subscriptions for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy "own progress" on public.episode_progress for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy "active plans readable" on public.membership_plans for select to anon,authenticated using(active=true);create policy "own membership" on public.memberships for select to authenticated using(user_id=(select auth.uid()));